function t1281_restoreTabHashOnShow(hookEl,hookElRecordType){if(window.T1281_TAB_BLOCKS.indexOf(hookElRecordType)===-1)return;var hookRecid=hookEl.id.replace('rec','');var tabParamsSource=t1281_getUrlParts().tabParams;var savedTabNumber=tabParamsSource[hookRecid]||t1281_findTabNumberByDeepestHash(hookRecid,tabParamsSource);var activeTabSelector='.t'+hookElRecordType+'__tab_active';var tabs=hookEl.querySelectorAll('.t'+hookElRecordType+'__tab');if(savedTabNumber&&tabs.length>=savedTabNumber){var targetTab=tabs[savedTabNumber-1];var currentActiveTab=hookEl.querySelector(activeTabSelector);if(targetTab&&targetTab!==currentActiveTab){t1281_activateTabDirect(hookEl,hookElRecordType,savedTabNumber);if(hookElRecordType==='1281'){t1281_updateContent(hookRecid)}}}
var activeTab=hookEl.querySelector(activeTabSelector);if(!activeTab){if(tabs.length>0){activeTab=tabs[0];activeTab.classList.add('t'+hookElRecordType+'__tab_active')}else{return}}
t1281_getTabRecIds(activeTab).forEach(function(nestedId){var nestedEl=document.getElementById('rec'+nestedId);if(nestedEl){t1281_restoreTabHashOnShow(nestedEl,t1281_getRecordType(nestedEl))}})}
function t1281_scrollToEl(el){var startPosition=window.pageYOffset;var startTime=null;var duration=300;function getElTopPos(){var elTopPos=el.getBoundingClientRect().top+window.pageYOffset;elTopPos=window.innerWidth>960?elTopPos-200:elTopPos-100;if(elTopPos<0)elTopPos=0;var documentHeight=Math.max(document.body.scrollHeight,document.documentElement.scrollHeight,document.body.offsetHeight,document.documentElement.offsetHeight,document.body.clientHeight,document.documentElement.clientHeight);var bottomViewportPoint=documentHeight-document.documentElement.clientHeight;if(elTopPos>bottomViewportPoint)elTopPos=bottomViewportPoint;return elTopPos}
function t1281_easeInQuad(timeElapsed,startPosition,distance,duration){timeElapsed/=duration;return distance*timeElapsed*timeElapsed+startPosition}
requestAnimationFrame(function scrollAnimation(currentTime){if(startTime===null)startTime=currentTime;var timeElapsed=currentTime-startTime;var elTopPos=getElTopPos();window.scrollTo(0,t1281_easeInQuad(timeElapsed,startPosition,elTopPos-startPosition,duration));document.body.setAttribute('data-scrollable','true');if(timeElapsed<duration){requestAnimationFrame(scrollAnimation)}else{window.scrollTo(0,elTopPos);document.body.removeAttribute('data-scrollable')}})}
function t1281_getRecordType(el){return el?el.getAttribute('data-parenttplid')||el.getAttribute('data-record-type'):''}
function t1281_isTabBlock(el){return window.T1281_TAB_BLOCKS.indexOf(t1281_getRecordType(el))!==-1}
function t1281_isBlockHidden(el){return(el.classList.contains('t1281__off')||el.classList.contains('t395__off')||el.classList.contains('t397__off'))}
function t1281_getTabRecIds(tab){var attr=tab.getAttribute('data-tab-rec-ids')||'';return attr?attr.split(',').filter(Boolean):[]}
function t1281_getLastRecidInHash(tabParams){var lastRecid=null;for(var recid in tabParams){if(tabParams.hasOwnProperty(recid)){lastRecid=recid}}
return lastRecid}
function t1281_updateBlock(type,recid){switch(type){case '1281':t1281_updateContent(recid);t1281_updateSelect(recid);break;case '395':if(window.t395_alltabs_updateContent)window.t395_alltabs_updateContent(recid);if(window.t395_updateSelect)window.t395_updateSelect(recid);break;case '397':if(window.t397_alltabs_updateContent)window.t397_alltabs_updateContent(recid);if(window.t397_updateSelect)window.t397_updateSelect(recid);break}}
function t1281_activateTabDirect(el,type,tabNumber){var tabSelector='.t'+type+'__tab';var activeSelector='.t'+type+'__tab_active';var tabs=el.querySelectorAll(tabSelector);if(tabs.length<tabNumber)return null;var currentActive=el.querySelector(activeSelector);if(currentActive){currentActive.classList.remove('t'+type+'__tab_active')}
tabs[tabNumber-1].classList.add('t'+type+'__tab_active');Array.prototype.forEach.call(tabs,function(tab,index){if(!tab.hasAttribute('data-tab-number')){tab.setAttribute('data-tab-number',index+1)}});var wrapper=el.querySelector('.t'+type+'__wrapper');if(wrapper)wrapper.setAttribute('data-tab-current',tabNumber);return tabs[tabNumber-1]}
function t1281_reloadIframes(el){var iframes=el.querySelectorAll('.t-video-lazyload iframe');if(!iframes.length)return;Array.prototype.forEach.call(iframes,function(iframe){var iframeSrc=iframe.getAttribute('src');if(iframeSrc)iframe.setAttribute('src',iframeSrc)})}